BEGIN;

-- Blok eksekusi cerdas: secara dinamis menentukan user_id dan nomor urut 'no' berikutnya
-- agar tidak terjadi duplikasi nomor dan kompatibel untuk user manapun.
DO $$
DECLARE
    v_target_user_id BIGINT;
    v_start_no INT;
BEGIN
    -- 1. Tentukan target user (prioritaskan superadmin_kamil id 2 pemilik data, fallback user pertama)
    SELECT id INTO v_target_user_id FROM public.users WHERE username = 'kamil';
